def entries_for(role):
    return [e for e in GUIDE if e['role'] == role]


def is_new(e, today=None):
    try:
        y, m, d = (int(x) for x in e['added'].split('-'))
        return ((today or date.today()) - date(y, m, d)).days <= NEW_DAYS
    except (ValueError, KeyError):
        return False


def covered_tiles():
    return {t for e in GUIDE for t in e.get('tiles', [])}


def roles_visible(user):
    """Which role tabs a signed-in user may read."""
    if getattr(user, 'is_admin', False):
        return ['admin', 'mentor', 'student', 'parent']
    if getattr(user, 'is_staff', False):
        return ['mentor', 'student', 'parent']
    return ['student', 'parent']
